from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse


def capability_forge_v3_ui_router() -> APIRouter:
    router = APIRouter(tags=["capability-forge-v3-ui"])

    @router.get("/capabilities/forge/production-readiness", response_class=HTMLResponse, include_in_schema=False)
    def page():
        return HTMLResponse(_PAGE, headers={
            "Cache-Control": "no-store", "Pragma": "no-cache", "Referrer-Policy": "no-referrer",
            "Content-Security-Policy": "default-src 'self'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'",
        })

    return router


_PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Vishnu · Forge V3</title><style>
:root{color-scheme:dark;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display",Inter,sans-serif;background:#07090d;color:#f4f7fb}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% 0,#15243a 0,#090d14 36%,#050609 100%);min-height:100dvh}main{max-width:1100px;margin:auto;padding:max(24px,env(safe-area-inset-top)) 18px max(30px,env(safe-area-inset-bottom))}a{color:#8fc8ff}header{display:flex;justify-content:space-between;gap:12px;align-items:center}.eyebrow{font-size:12px;color:#8fa1ba;text-transform:uppercase;letter-spacing:.12em}h1{font-size:34px;margin:8px 0}.sub{max-width:760px;color:#9ca9ba;line-height:1.5}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:12px;margin-top:20px}.card{background:rgba(15,20,30,.82);border:1px solid #273246;border-radius:18px;padding:16px;backdrop-filter:blur(14px)}h2{font-size:18px;margin:0 0 10px}.check{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #202a3a;font-size:13px}.ok{color:#8fe0b5}.bad{color:#f0a9b1}.muted{color:#93a0b2;font-size:12px;line-height:1.45}.blocker{background:#251318;border:1px solid #5a2e38;border-radius:10px;padding:9px;margin:7px 0;color:#efbdc5;font-size:12px}label{display:block;color:#aab7c8;font-size:12px;margin:10px 0 5px}input,select,textarea{width:100%;background:#080c12;color:#eef4ff;border:1px solid #334159;border-radius:10px;padding:10px;font:inherit;font-size:13px}textarea{min-height:90px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.btn{border:0;border-radius:10px;padding:9px 12px;font-weight:700;margin-top:10px;background:#d9e8ff;color:#101827;cursor:pointer}.btn.secondary{background:#182437;color:#d9e8ff;border:1px solid #34445e}.status{min-height:20px;margin-top:9px;color:#9eb0c7;font-size:12px;white-space:pre-wrap}.cap{padding:9px;border:1px solid #273246;border-radius:10px;margin-top:8px;font-size:12px}.footer{margin-top:20px;color:#8492a6;font-size:12px;line-height:1.5}
</style></head><body><main><header><div><div class="eyebrow">Capability Forge V3</div><h1>Production readiness</h1></div><a href="/capabilities/forge">Back to Forge</a></header><p class="sub">Owner-only readiness, provider verification, capability OAuth and staged canary controls. This surface can remove or stage authority, but it cannot self-approve production activation.</p>
<div class="grid"><section class="card"><h2>Readiness gates</h2><div id="checks">Loading…</div><div id="blockers"></div><button class="btn secondary" id="refresh">Refresh</button></section>
<section class="card"><h2>Capability OAuth</h2><p class="muted">OAuth tokens stay in Vishnu's vault. Forge stores only the capability-to-provider binding.</p><label>Capability ID</label><input id="oauth-cap" autocomplete="off"><label>Provider</label><select id="oauth-provider"></select><label>Requested scopes (comma separated, optional)</label><input id="oauth-scopes" autocomplete="off"><button class="btn" id="oauth-start">Connect provider</button><button class="btn secondary" id="oauth-status">Check status</button><div class="status" id="oauth-out"></div></section>
<section class="card"><h2>Staged canary</h2><div class="row"><div><label>Capability ID</label><input id="can-cap"></div><div><label>Version</label><input id="can-ver" value="1.0.0"></div></div><label>Packaged build ID</label><input id="can-build"><label>Canary parameters (JSON)</label><textarea id="can-params">{}</textarea><button class="btn" id="can-run">Run current-stage canary</button><button class="btn secondary" id="can-state">Read rollout state</button><label>Promotion target</label><select id="can-target"><option value="limited">limited</option><option value="broad_eligible">broad_eligible</option></select><label>Approval ID (leave blank to request)</label><input id="can-ticket"><button class="btn secondary" id="can-promote">Request / commit promotion</button><div class="status" id="can-out"></div></section>
<section class="card"><h2>Live provider verification</h2><p class="muted">Only existing read-only ToolRegistry tools can be used. Provider response bodies are never displayed here.</p><label>Tool name</label><input id="probe-tool"><label>Parameters (JSON)</label><textarea id="probe-params">{}</textarea><button class="btn" id="probe-run">Verify provider</button><div class="status" id="probe-out"></div></section>
<section class="card"><h2>Generated capabilities</h2><div id="caps">Loading…</div></section></div><div class="footer">Production domains, provider OAuth clients, Android signing fingerprints and Apple association IDs are deployment configuration. Their absence keeps production readiness blocked; the console does not manufacture or hard-code them.</div>
<script>
async function api(path,method='GET',body){const r=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:(d.detail?.message||`Request failed (${r.status})`));return d}
const out=(id,v)=>document.getElementById(id).textContent=typeof v==='string'?v:JSON.stringify(v,null,2);
async function load(){try{const r=await api('/iphone/api/owner/forge/v3/readiness');const c=document.getElementById('checks');c.innerHTML='';Object.entries(r.checks||{}).forEach(([k,v])=>{const e=document.createElement('div');e.className='check';const a=document.createElement('span');a.textContent=k.replaceAll('_',' ');const b=document.createElement('strong');b.className=v?'ok':'bad';b.textContent=v?'PASS':'BLOCKED';e.append(a,b);c.append(e)});const bl=document.getElementById('blockers');bl.innerHTML='';(r.blockers||[]).forEach(x=>{const e=document.createElement('div');e.className='blocker';e.textContent=x;bl.append(e)});if(!r.blockers?.length){const e=document.createElement('div');e.className='status ok';e.textContent='All configuration/readiness checks pass. Production activation authority is still separate.';bl.append(e)}}catch(e){out('blockers',e.message)}try{const p=await api('/iphone/api/owner/forge/v3/oauth/providers');const s=document.getElementById('oauth-provider');s.innerHTML='';(p.items||[]).forEach(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=`${x.id} · ${x.scopes.join(', ')}`;s.append(o)})}catch{}try{const g=await api('/iphone/api/owner/forge/capabilities');const c=document.getElementById('caps');c.innerHTML='';(g.items||[]).forEach(x=>{const e=document.createElement('div');e.className='cap';e.textContent=`${x.id} · ${x.version||''} · ${x.state||''} · provenance ${x.provenance_required?'V3':'legacy'} · rollout ${x.rollout_stage||'not broad-eligible'}`;c.append(e)});if(!(g.items||[]).length)c.textContent='No generated capabilities.'}catch(e){out('caps',e.message)}}
document.getElementById('refresh').onclick=load;document.getElementById('oauth-start').onclick=async()=>{try{const scopes=document.getElementById('oauth-scopes').value.split(',').map(x=>x.trim()).filter(Boolean);const r=await api(`/iphone/api/owner/forge/v3/oauth/${encodeURIComponent(document.getElementById('oauth-cap').value)}/${encodeURIComponent(document.getElementById('oauth-provider').value)}/start`,'POST',{scopes});out('oauth-out','Opening provider authorization…');location.assign(r.url)}catch(e){out('oauth-out',e.message)}};document.getElementById('oauth-status').onclick=async()=>{try{out('oauth-out',await api(`/iphone/api/owner/forge/v3/oauth/${encodeURIComponent(document.getElementById('oauth-cap').value)}/status`))}catch(e){out('oauth-out',e.message)}};
document.getElementById('can-run').onclick=async()=>{try{const c=encodeURIComponent(document.getElementById('can-cap').value),v=encodeURIComponent(document.getElementById('can-ver').value),parameters=JSON.parse(document.getElementById('can-params').value||'{}');out('can-out',await api(`/iphone/api/owner/forge/v3/rollout/${c}/${v}/canary`,'POST',{build_id:document.getElementById('can-build').value,parameters}))}catch(e){out('can-out',e.message)}};document.getElementById('can-state').onclick=async()=>{try{out('can-out',await api(`/iphone/api/owner/forge/v3/rollout/${encodeURIComponent(document.getElementById('can-cap').value)}/${encodeURIComponent(document.getElementById('can-ver').value)}`))}catch(e){out('can-out',e.message)}};document.getElementById('can-promote').onclick=async()=>{try{const c=encodeURIComponent(document.getElementById('can-cap').value),v=encodeURIComponent(document.getElementById('can-ver').value),ticket=document.getElementById('can-ticket').value.trim();const r=await api(`/iphone/api/owner/forge/v3/rollout/${c}/${v}/promotion`,'POST',{target_stage:document.getElementById('can-target').value,ticket_id:ticket||null});if(r.approval_id&&!ticket)document.getElementById('can-ticket').value=r.approval_id;out('can-out',r)}catch(e){out('can-out',e.message)}};
document.getElementById('probe-run').onclick=async()=>{try{out('probe-out',await api('/iphone/api/owner/forge/v3/providers/verify','POST',{tool_name:document.getElementById('probe-tool').value,parameters:JSON.parse(document.getElementById('probe-params').value||'{}')}))}catch(e){out('probe-out',e.message)}};load();
</script></main></body></html>'''
